8	import { canonicalIds, flatten, pathMatches, type Json } from "./json.ts";
9	
10	const Why = z.string().min(5);
11	const Field = z.discriminatedUnion("mode", [
12	  z.object({ path: z.string(), mode: z.literal("ignore"), why: Why }),
13	  z.object({ path: z.string(), mode: z.literal("type"), why: Why }),
14	  z.object({ path: z.string(), mode: z.literal("tolerance"), by: z.number().positive(), why: Why }),
15	  z.object({
16	    path: z.string(),
17	    mode: z.literal("perceptual"),
18	    // Share of thumbnail cells allowed to differ before the difference is reported.
19	    max_share: z.number().min(0).max(1),
20	    why: Why,
21	  }),
22	]);
23	export type PolicyField = z.infer<typeof Field>;
24	
25	export const PolicySchema = z.object({
26	  canonicalIds: z.boolean().describe("rename generated IDs before comparing"),
27	  fields: z.array(Field),
28	});
29	export type Policy = z.infer<typeof PolicySchema>;
30	
31	export interface FieldDiff {
32	  path: string;
33	  expected: Json | undefined;
34	  actual: Json | undefined;
35	  // Set on perceptual differences: reported, never counted against the case.
36	  report?: { share: number };
37	}
38	
39	const typeOf = (v: Json | undefined): string =>
40	  v === undefined ? "absent" : v === null ? "null" : Array.isArray(v) ? "array" : typeof v;
41	
42	// A thumbnail is "<width>x<height>:<base64 luminance bytes>"; masked cells hold 255 on both sides.
43	const CELL_DELTA = 24;
44	export function thumbnailShare(e: Json | undefined, a: Json | undefined): number {
45	  if (typeof e !== "string" || typeof a !== "string") return 1;
46	  const [eSize, eData = ""] = e.split(":");
47	  const [aSize, aData = ""] = a.split(":");
48	  if (eSize !== aSize) return 1;
49	  const x = Buffer.from(eData, "base64");
50	  const y = Buffer.from(aData, "base64");
51	  if (x.length !== y.length || x.length === 0) return 1;
52	  let off = 0;
53	  for (let i = 0; i < x.length; i++) if (Math.abs((x[i] ?? 0) - (y[i] ?? 0)) > CELL_DELTA) off++;
54	  return off / x.length;
55	}
