57	function compare(field: PolicyField | undefined, path: string, ev?: Json, av?: Json): FieldDiff[] {
58	  const d = { path, expected: ev, actual: av };
59	  switch (field?.mode) {
60	    case "ignore":
61	      return [];
62	    case "type":
63	      return typeOf(ev) === typeOf(av) ? [] : [d];
64	    case "tolerance":
65	      return typeof ev === "number" && typeof av === "number" && Math.abs(ev - av) <= field.by
66	        ? []
67	        : [d];
68	    case "perceptual": {
69	      const share = thumbnailShare(ev, av);
70	      return share <= field.max_share ? [] : [{ ...d, report: { share } }];
71	    }
72	    case undefined:
73	      return JSON.stringify(ev) === JSON.stringify(av) ? [] : [d];
74	  }
75	}
