80	  const a = prep(actual);
81	  const out: FieldDiff[] = [];
82	  for (const path of new Set([...e.keys(), ...a.keys()])) {
83	    const field = policy.fields.find((f) => pathMatches(f.path, path));
84	    out.push(...compare(field, path, e.get(path), a.get(path)));
85	  }
86	  return out.sort((x, y) => x.path.localeCompare(y.path));
87	}
