140	export function writeLock(target: string): void {
141	  writeFileSync(lockPath(target), `${JSON.stringify(currentHashes(target), null, 2)}\n`);
142	}
143	
144	// Returns the list of mismatches; empty means the evaluator is intact.
145	export function checkLock(target: string): string[] {
146	  if (!existsSync(lockPath(target))) return ["fixtures.lock is missing"];
147	  const locked = LockSchema.parse(JSON.parse(readFileSync(lockPath(target), "utf8")));
148	  const now = currentHashes(target);
149	  const problems: string[] = [];
150	  if (locked.policy !== now.policy) problems.push("policy.json changed");
151	  if (locked.code === undefined) problems.push("lock has no code hashes (run relock)");
152	  for (const [f, h] of Object.entries(locked.code ?? {})) {
153	    if (now.code?.[f] !== h) problems.push(`${f} changed`);
154	  }
155	  for (const f of Object.keys(now.code ?? {})) {
156	    if (locked.code?.[f] === undefined) problems.push(`${f} not in lock`);
157	  }
158	  // In a builder sandbox the holdout folder does not exist at all; that is the point of it.
159	  const holdoutAbsent = !existsSync(fixturesDir(target, "holdout"));
160	  for (const [f, h] of Object.entries(locked.fixtures)) {
161	    if (holdoutAbsent && f.startsWith("holdout/")) continue;
162	    if (now.fixtures[f] === undefined) problems.push(`${f} missing`);
163	    else if (now.fixtures[f] !== h) problems.push(`${f} changed`);
164	  }
165	  for (const f of Object.keys(now.fixtures)) {
166	    if (locked.fixtures[f] === undefined) problems.push(`${f} not in lock`);
167	  }
168	  return problems;
169	}
