1	/**
2	 * JSON helpers shared by the recorder and the verifier: a stable flattening of any value into
3	 * `path -> leaf` pairs, and canonical renaming of generated IDs so that two systems that mint
4	 * different IDs can still be compared on the references between objects.
5	 */
6	
7	import { z } from "zod";
8	
9	export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
10	
11	export const JsonSchema: z.ZodType<Json> = z.lazy(() =>
12	  z.union([
13	    z.null(),
14	    z.boolean(),
15	    z.number(),
16	    z.string(),
17	    z.array(JsonSchema),
18	    z.record(z.string(), JsonSchema),
19	  ]),
20	);
21	
22	export function flatten(
23	  value: Json,
24	  prefix = "",
25	  out = new Map<string, Json>(),
26	): Map<string, Json> {
27	  if (Array.isArray(value)) {
28	    if (value.length === 0) out.set(prefix, []);
29	    value.forEach((v, i) => flatten(v, `${prefix}[${i}]`, out));
30	  } else if (value !== null && typeof value === "object") {
31	    const keys = Object.keys(value).sort();
32	    if (keys.length === 0) out.set(prefix, {});
33	    for (const k of keys) flatten(value[k] ?? null, prefix === "" ? k : `${prefix}.${k}`, out);
34	  } else {
35	    out.set(prefix, value);
36	  }
37	  return out;
38	}
39	
40	// A path pattern uses `[*]` for any index, `*` for any single key segment, and a trailing `.**`
41	// for the whole subtree under a path.
42	export function pathMatches(pattern: string, path: string): boolean {
43	  const subtree = pattern.endsWith(".**");
44	  const re = (subtree ? pattern.slice(0, -3) : pattern)
45	    .split(/(\[\*\]|\*)/)
46	    .map((part) => {
47	      if (part === "[*]") return String.raw`\[\d+\]`;
48	      if (part === "*") return String.raw`[^.\[]+`;
49	      return part.replace(/[.[\]()^$+?{}|\\]/g, (c) => `\\${c}`);
50	    })
51	    .join("");
52	  return new RegExp(`^${re}${subtree ? String.raw`(?:[.[].*)?` : ""}$`).test(path);
53	}
54	
55	const GENERATED_ID = /^([a-z]+(?:_[a-z]+)*)_([A-Za-z0-9]{8,})$/;
56	
57	// Replaces every generated ID with `<prefix>#<n>`, n being the order of first appearance in a
58	// key-sorted traversal. Equal IDs stay equal, so references between objects are still checked.
59	export function canonicalIds(value: Json): Json {
60	  const seen = new Map<string, string>();
61	  const counters = new Map<string, number>();
62	  const rename = (s: string): string => {
63	    const m = GENERATED_ID.exec(s);
64	    if (!m?.[1]) return s;
65	    const known = seen.get(s);
66	    if (known) return known;
67	    const n = (counters.get(m[1]) ?? 0) + 1;
68	    counters.set(m[1], n);
69	    const name = `${m[1]}#${n}`;
70	    seen.set(s, name);
71	    return name;
72	  };
73	  const walk = (v: Json): Json => {
74	    if (typeof v === "string") {
75	      return v.replace(/[a-z]+(?:_[a-z]+)*_[A-Za-z0-9]{8,}/g, (id) => rename(id));
76	    }
77	    if (Array.isArray(v)) return v.map(walk);
78	    if (v !== null && typeof v === "object") {
79	      const o: Record<string, Json> = {};
80	      for (const k of Object.keys(v).sort()) o[k] = walk(v[k] ?? null);
81	      return o;
82	    }
83	    return v;
84	  };
85	  return walk(value);
86	}
