1	/**
2	 * Slice 2: the subscription lifecycle over time. A lifecycle probe is a script of actions on one
3	 * subscription living on a test clock (cancel at period end, reactivate, cancel now, advance the
4	 * clock, swap in a failing card), with a snapshot of the subscription and its latest invoice after
5	 * the steps that matter. Snapshots are a projection: fields outside it are not compared.
6	 */
7	import type Stripe from "stripe";
8	import { z } from "zod";
9	import type { Json } from "../../harness/src/json.ts";
10	
11	export const LifeStep = z.discriminatedUnion("do", [
12	  z.object({ do: z.literal("cancel_at_period_end") }),
13	  z.object({ do: z.literal("reactivate") }),
14	  z.object({ do: z.literal("cancel_now"), prorate: z.boolean(), invoice_now: z.boolean() }),
15	  z.object({ do: z.literal("advance"), seconds: z.number() }),
16	  z.object({ do: z.literal("failing_card") }),
17	  z.object({ do: z.literal("snapshot"), as: z.string() }),
18	]);
19	export type LifeStep = z.infer<typeof LifeStep>;
20	
21	export const LifeInput = z.object({
22	  kind: z.literal("lifecycle"),
23	  start: z.number(),
24	  amount: z.number(),
25	  trial_days: z.number().nullable(),
26	  steps: z.array(LifeStep),
27	});
28	export type LifeInput = z.infer<typeof LifeInput>;
