30	export function invoiceView(inv: Stripe.Invoice | null): Json {
31	  if (!inv) return null;
32	  return {
33	    status: inv.status ?? null,
34	    billing_reason: inv.billing_reason ?? null,
35	    subtotal: inv.subtotal,
36	    total: inv.total,
37	    amount_due: inv.amount_due,
38	    amount_paid: inv.amount_paid,
39	    amount_remaining: inv.amount_remaining,
40	    attempt_count: inv.attempt_count,
41	    period_start: inv.period_start,
42	    period_end: inv.period_end,
43	    lines: inv.lines.data.map((l) => ({ amount: l.amount, description: l.description ?? null })),
44	  };
45	}
