47	async function waitReady(stripe: Stripe, clock: string): Promise<void> {
48	  for (let i = 0; i < 60; i += 1) {
49	    const c = await stripe.testHelpers.testClocks.retrieve(clock);
50	    if (c.status === "ready") return;
51	    await new Promise((r) => setTimeout(r, 1000));
52	  }
53	  throw new Error(`test clock ${clock} did not become ready`);
54	}
55	
56	export async function runLifecycle(
57	  stripe: Stripe,
58	  input: LifeInput,
59	): Promise<Record<string, Json>> {
60	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: input.start });
61	  const product = await stripe.products.create({ name: "Basic" });
62	  const price = await stripe.prices.create({
63	    product: product.id,
64	    currency: "usd",
65	    unit_amount: input.amount,
66	    recurring: { interval: "month" },
67	  });
68	  const customer = await stripe.customers.create({
69	    test_clock: clock.id,
70	    payment_method: "pm_card_visa",
71	    invoice_settings: { default_payment_method: "pm_card_visa" },
72	    preferred_locales: ["en"],
73	  });
74	  const created = await stripe.subscriptions.create({
75	    customer: customer.id,
76	    items: [{ price: price.id }],
77	    ...(input.trial_days !== null ? { trial_period_days: input.trial_days } : {}),
78	  });
79	  let now = input.start;
80	  const out: Record<string, Json> = {};
81	  for (const step of input.steps) {
82	    if (step.do === "cancel_at_period_end" || step.do === "reactivate") {
83	      await stripe.subscriptions.update(created.id, {
84	        cancel_at_period_end: step.do === "cancel_at_period_end",
85	      });
86	    } else if (step.do === "cancel_now") {
87	      await stripe.subscriptions.cancel(created.id, {
88	        prorate: step.prorate,
89	        invoice_now: step.invoice_now,
90	      });
91	    } else if (step.do === "advance") {
92	      now += step.seconds;
93	      await stripe.testHelpers.testClocks.advance(clock.id, { frozen_time: now });
94	      await waitReady(stripe, clock.id);
95	    } else if (step.do === "failing_card") {
96	      const pm = await stripe.paymentMethods.attach("pm_card_chargeCustomerFail", {
97	        customer: customer.id,
98	      });
99	      await stripe.customers.update(customer.id, {
100	        invoice_settings: { default_payment_method: pm.id },
101	      });
102	    } else {
103	      const sub = await stripe.subscriptions.retrieve(created.id, { expand: ["latest_invoice"] });
104	      const item = sub.items.data[0];
105	      const latest = typeof sub.latest_invoice === "object" ? sub.latest_invoice : null;
106	      const invoices = await stripe.invoices.list({ subscription: sub.id, limit: 10 });
107	      out[step.as] = {
108	        status: sub.status,
109	        cancel_at_period_end: sub.cancel_at_period_end,
110	        cancel_at: sub.cancel_at ?? null,
111	        canceled_at: sub.canceled_at ?? null,
112	        ended_at: sub.ended_at ?? null,
113	        trial_end: sub.trial_end ?? null,
114	        period_start: item?.current_period_start ?? null,
115	        period_end: item?.current_period_end ?? null,
116	        latest_invoice: invoiceView(latest),
117	        invoice_count: invoices.data.length,
118	      };
119	    }
120	  }
121	  return out;
122	}
