1	/**
2	 * State-graph exploration of the Customer Portal: walkthroughs only check the paths someone
3	 * thought of, so this probe clicks every visible, enabled button and same-site link, breadth
4	 * first, up to a depth, and records the graph of screens it reaches. Each path is replayed in a
5	 * fresh billing world, since a click can change the account. The graph is canonical (states
6	 * numbered in discovery order, actions in page order), so the same code on the clone must
7	 * reach the same screens through the same clicks.
8	 */
9	import type { Browser, Page } from "playwright";
10	import type Stripe from "stripe";
11	import { z } from "zod";
12	import type { Json } from "../../harness/src/json.ts";
13	import { launch, normalise, openPage, settle, setupWorld, World } from "./ui.ts";
14	
15	export const ExploreInput = World.extend({
16	  kind: z.literal("explore"),
17	  depth: z.number().int().min(1).max(4),
18	  max_states: z.number().int().min(1).max(40),
19	});
20	export type ExploreInput = z.infer<typeof ExploreInput>;
21	
22	interface Action {
23	  role: "button" | "link";
24	  name: string;
25	  nth: number;
26	}
27	
28	const label = (a: Action): string => `${a.role} "${a.name}"${a.nth > 0 ? ` #${a.nth}` : ""}`;
29	
30	// Waits until the accessibility tree has not changed for a second: screens animate in, and
31	// buttons show a transient label ("Canceling…") while their request runs.
32	async function stableScreen(page: Page): Promise<string[]> {
33	  await settle(page);
34	  let last = "";
35	  let same = 0;
36	  for (let i = 0; i < 40 && same < 2; i += 1) {
37	    await page.waitForTimeout(500);
38	    const now = await page.locator("body").ariaSnapshot();
39	    same = now === last ? same + 1 : 0;
40	    last = now;
41	  }
42	  return normalise(last);
43	}
44	
45	async function actions(page: Page): Promise<Action[]> {
46	  const origin = new URL(page.url()).origin;
47	  const out: Action[] = [];
48	  const seen = new Map<string, number>();
49	  for (const role of ["link", "button"] as const) {
50	    for (const el of await page.getByRole(role).all()) {
51	      const aria = await el.ariaSnapshot().catch(() => "");
52	      const name = /^- \w+ "((?:[^"\\]|\\.)*)"/.exec(aria)?.[1];
53	      if (name === undefined) continue;
54	      const key = `${role}\u0000${name}`;
55	      const nth = seen.get(key) ?? 0;
56	      seen.set(key, nth + 1);
57	      if (!(await el.isVisible()) || !(await el.isEnabled())) continue;
58	      const href = await el.getAttribute("href");
59	      if (href !== null && !href.startsWith("#") && new URL(href, page.url()).origin !== origin)
60	        continue;
61	      out.push({ role, name: name.replace(/\\(.)/g, "$1"), nth });
62	    }
63	  }
64	  return out;
65	}
66	
67	async function replay(
68	  browser: Browser,
69	  stripe: Stripe,
70	  world: World,
71	  path: Action[],
72	): Promise<{ screen: string[]; next: Action[] }> {
73	  const portal = await setupWorld(stripe, world);
74	  const page = await openPage(browser);
75	  try {
76	    await page.goto(portal.url);
77	    await page.getByRole("link").first().waitFor({ timeout: 20000 });
78	    for (const a of path) {
79	      await page.getByRole(a.role, { name: a.name, exact: true }).nth(a.nth).click();
80	      await stableScreen(page);
81	    }
82	    return { screen: await stableScreen(page), next: await actions(page) };
83	  } finally {
84	    await page.context().close();
85	  }
86	}
87	
88	export async function runExplore(
89	  stripe: Stripe,
90	  input: ExploreInput,
91	): Promise<Record<string, Json>> {
92	  const browser = await launch();
93	  const states = new Map<string, number>();
94	  const screens: string[][] = [];
95	  const edges: { from: number; action: string; to: number }[] = [];
96	  const queue: { path: Action[]; from: number | null }[] = [{ path: [], from: null }];
97	  let truncated = false;
98	  try {
99	    for (let node = queue.shift(); node; node = queue.shift()) {
100	      const { screen, next } = await replay(browser, stripe, input, node.path);
101	      const sig = screen.join("\n");
102	      const known = states.get(sig);
103	      const id = known ?? screens.length;
104	      const last = node.path.at(-1);
105	      if (node.from !== null && last) edges.push({ from: node.from, action: label(last), to: id });
106	      if (known !== undefined) continue;
107	      if (screens.length >= input.max_states) {
108	        truncated = true;
109	        break;
110	      }
111	      states.set(sig, id);
112	      screens.push(screen);
113	      if (node.path.length >= input.depth) continue;
114	      for (const a of next) queue.push({ path: [...node.path, a], from: id });
115	    }
116	  } finally {
117	    await browser.close();
118	  }
119	  return { graph: { states: screens, edges, truncated } };
120	}
121

1	/**
2	 * UI probes for the Customer Portal. A walkthrough is data (actions and the text each screen must
3	 * show before it is captured), so the same steps drive the real portal and the clone's. A capture
4	 * is the page's accessibility tree without link targets, plus the portal API calls the step fired.
5	 * With `capture: "full"` it also holds each call's request body, the layout of the visible
6	 * elements and a masked luminance thumbnail, and the walkthrough ends with the account state it
7	 * left behind, read through the public API: what the clicks actually did.
8	 */
9	import { chromium, type Browser, type Page } from "playwright";
10	import type Stripe from "stripe";
11	import { z } from "zod";
12	import { JsonSchema, type Json } from "../../harness/src/json.ts";
13	import { invoiceView } from "./lifecycle.ts";
14	
15	export const Step = z.discriminatedUnion("do", [
16	  z.object({
17	    do: z.literal("click"),
18	    role: z.enum(["button", "link"]),
19	    name: z.string(),
20	    nth: z.number().optional(),
21	  }),
22	  z.object({ do: z.literal("hoverIconAfter"), text: z.string() }),
23	  z.object({ do: z.literal("capture"), as: z.string(), until: z.string() }),
24	]);
25	export type Step = z.infer<typeof Step>;
26	
27	export const World = z.object({
28	  start: z.number(),
29	  current: z.enum(["Basic", "Pro"]),
30	  coupon_percent: z.number().nullable(),
31	  // Slice 2. Absent in slice 1 fixtures, which were recorded with cancellation disabled.
32	  cancel_enabled: z.boolean().default(false),
33	  quantity: z.number().default(1),
34	});
35	export type World = z.infer<typeof World>;
36	
37	export const UiInput = World.extend({
38	  kind: z.literal("ui"),
39	  // "screen" is the original capture; fixtures recorded before "full" existed keep it.
40	  capture: z.enum(["screen", "full"]).default("screen"),
41	  steps: z.array(Step),
42	});
43	export type UiInput = z.infer<typeof UiInput>;
44	
45	export const PLANS = { Basic: 1000, Pro: 3000 } as const;
46	export const VIEWPORT = { width: 1280, height: 800 };
47	const THUMB = { width: 64, height: 40 };
48	
49	export interface Portal {
50	  url: string;
51	  subscription: string;
52	}
53	
54	export async function setupWorld(stripe: Stripe, w: World): Promise<Portal> {
55	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: w.start });
56	  const prices: Record<string, string> = {};
57	  const products: { product: string; prices: string[] }[] = [];
58	  for (const name of ["Basic", "Pro"] as const) {
59	    const product = await stripe.products.create({ name });
60	    const price = await stripe.prices.create({
61	      product: product.id,
62	      currency: "usd",
63	      unit_amount: PLANS[name],
64	      recurring: { interval: "month" },
65	    });
66	    prices[name] = price.id;
67	    products.push({ product: product.id, prices: [price.id] });
68	  }
69	  const customer = await stripe.customers.create({
70	    test_clock: clock.id,
71	    payment_method: "pm_card_visa",
72	    invoice_settings: { default_payment_method: "pm_card_visa" },
73	    preferred_locales: ["en"],
74	  });
75	  const coupon =
76	    w.coupon_percent !== null
77	      ? await stripe.coupons.create({ duration: "forever", percent_off: w.coupon_percent })
78	      : null;
79	  const subscription = await stripe.subscriptions.create({
80	    customer: customer.id,
81	    items: [
82	      { price: prices[w.current] ?? "", ...(w.quantity !== 1 ? { quantity: w.quantity } : {}) },
83	    ],
84	    ...(coupon ? { discounts: [{ coupon: coupon.id }] } : {}),
85	  });
86	  const configuration = await stripe.billingPortal.configurations.create({
87	    features: {
88	      payment_method_update: { enabled: true },
89	      ...(w.cancel_enabled
90	        ? {
91	            subscription_cancel: {
92	              enabled: true,
93	              mode: "at_period_end" as const,
94	              // The API wants two options even with the reason prompt disabled.
95	              cancellation_reason: {
96	                enabled: false,
97	                options: ["other" as const, "unused" as const],
98	              },
99	            },
100	          }
101	        : {}),
102	      subscription_update: {
103	        enabled: true,
104	        default_allowed_updates: w.quantity !== 1 ? ["price", "quantity"] : ["price"],
105	        proration_behavior: "create_prorations",
106	        products,
107	      },
108	    },
109	  });
110	  const session = await stripe.billingPortal.sessions.create({
111	    customer: customer.id,
112	    configuration: configuration.id,
113	  });
114	  return { url: session.url, subscription: subscription.id };
115	}
116	
117	export function normalise(aria: string): string[] {
118	  return aria
119	    .split("\n")
120	    .filter((l) => !/^\s*- \/url:/.test(l))
121	    .map((l) => l.replace(/\s+$/, ""));
122	}
123	
124	async function act(page: Page, step: Step): Promise<void> {
125	  if (step.do === "click") {
126	    await page
127	      .getByRole(step.role, { name: step.name, exact: true })
128	      .nth(step.nth ?? 0)
129	      .click();
130	  } else if (step.do === "hoverIconAfter") {
131	    await page
132	      .getByText(step.text, { exact: true })
133	      .first()
134	      .locator("xpath=following::*[name()='svg'][1]")
135	      .hover();
136	    await page.getByRole("tooltip").first().waitFor({ timeout: 5000 });
137	  }
138	}
139	
140	// Form bodies become sorted key/value objects so that parameter order never matters.
141	function parseBody(raw: string | null, type: string | undefined): Json {
142	  if (raw === null || raw === "") return null;
143	  if (type?.includes("json") === true) {
144	    try {
145	      return JsonSchema.parse(JSON.parse(raw));
146	    } catch {
147	      return raw;
148	    }
149	  }
150	  const params = new URLSearchParams(raw);
151	  return Object.fromEntries([...params.keys()].sort().map((k) => [k, params.getAll(k).join(",")]));
152	}
153	
154	export interface Recorder {
155	  take(): Promise<Json[]>;
156	}
157	
158	// Records the portal API calls a page fires: method and path, plus body and status when full.
159	export function watchPortalCalls(page: Page, full: boolean): Recorder {
160	  const pending: Promise<Json>[] = [];
161	  page.on("request", (r) => {
162	    const u = new URL(r.url());
163	    if (!u.pathname.startsWith("/v1/billing_portal/")) return;
164	    const line = `${r.method()} ${u.pathname}`;
165	    if (!full) {
166	      pending.push(Promise.resolve(line));
167	      return;
168	    }
169	    const body = parseBody(r.postData(), r.headers()["content-type"]);
170	    pending.push(
171	      r
172	        .response()
173	        .then((res) => ({ call: line, body, status: res?.status() ?? null }))
174	        .catch(() => ({ call: line, body, status: null })),
175	    );
176	  });
177	  return { take: async () => Promise.all(pending.splice(0)) };
178	}
179	
180	const LAYOUT_ROLES =
181	  "a,button,h1,h2,h3,h4,input,select,textarea,[role=button],[role=link],[role=tooltip]";
182	
183	// Visible landmarks of the page with their boxes ([x, y, width, height]), in document order. Text blocks count when they
184	// hold their own text, so that a moved price or label shows up even if no control moved.
185	async function layout(page: Page): Promise<Json> {
186	  // No named helpers inside: tsx would wrap them in a helper the browser does not have.
187	  const boxes = await page.evaluate((selector) => {
188	    const candidates = [...document.querySelectorAll(selector)];
189	    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
190	    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
191	      const parent = n.parentElement;
192	      if (parent && (n.textContent ?? "").trim() !== "" && !parent.closest(selector))
193	        candidates.push(parent);
194	    }
195	    const ordered = [...new Set(candidates)].sort((x, y) =>
196	      x.compareDocumentPosition(y) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1,
197	    );
198	    const out: { tag: string; text: string; box: number[] }[] = [];
199	    for (const el of ordered) {
200	      const r = el.getBoundingClientRect();
201	      if (r.width === 0 || r.height === 0) continue;
202	      const text = (el instanceof HTMLElement ? el.innerText : el.textContent)
203	        .replace(/\s+/g, " ")
204	        .trim()
205	        .slice(0, 60);
206	      const tag = el.getAttribute("role") ?? el.tagName.toLowerCase();
207	      out.push({ tag, text, box: [r.x, r.y, r.width, r.height].map(Math.round) });
208	    }
209	    return out;
210	  }, LAYOUT_ROLES);
211	  // Keyed by element, not by index, so that one missing element does not shift all the others.
212	  const keyed: Record<string, Json> = {};
213	  const seen = new Map<string, number>();
214	  for (const b of boxes) {
215	    const base = `${b.tag} ${b.text}`;
216	    const n = seen.get(base) ?? 0;
217	    seen.set(base, n + 1);
218	    keyed[n === 0 ? base : `${base} #${n + 1}`] = b.box;
219	  }
220	  return keyed;
221	}
222	
223	// A grey-level thumbnail of the viewport, iframes masked (third-party payment widgets). Decoding
224	// happens in a blank page of the same browser, so no image library is needed.
225	async function thumbnail(browser: Browser, page: Page): Promise<string> {
226	  const masks = await page.locator("iframe").evaluateAll((els) =>
227	    els.map((e) => {
228	      const r = e.getBoundingClientRect();
229	      return [r.x, r.y, r.width, r.height];
230	    }),
231	  );
232	  const png = (await page.screenshot({ animations: "disabled", caret: "hide" })).toString("base64");
233	  const scratch = await browser.newPage();
234	  try {
235	    return await scratch.evaluate(
236	      async ({ png, masks, thumb, viewport }) => {
237	        const img = new Image();
238	        img.src = `data:image/png;base64,${png}`;
239	        await img.decode();
240	        const canvas = document.createElement("canvas");
241	        canvas.width = viewport.width;
242	        canvas.height = viewport.height;
243	        const ctx = canvas.getContext("2d");
244	        if (!ctx) throw new Error("no 2d context");
245	        ctx.drawImage(img, 0, 0, viewport.width, viewport.height);
246	        ctx.fillStyle = "#fff";
247	        for (const [x = 0, y = 0, w = 0, h = 0] of masks) ctx.fillRect(x, y, w, h);
248	        const small = document.createElement("canvas");
249	        small.width = thumb.width;
250	        small.height = thumb.height;
251	        const sctx = small.getContext("2d");
252	        if (!sctx) throw new Error("no 2d context");
253	        sctx.imageSmoothingQuality = "high";
254	        sctx.drawImage(canvas, 0, 0, thumb.width, thumb.height);
255	        const { data } = sctx.getImageData(0, 0, thumb.width, thumb.height);
256	        let bin = "";
257	        for (let i = 0; i < data.length; i += 4) {
258	          const lum =
259	            0.299 * (data[i] ?? 0) + 0.587 * (data[i + 1] ?? 0) + 0.114 * (data[i + 2] ?? 0);
260	          bin += String.fromCharCode(Math.round(lum));
261	        }
262	        return `${thumb.width}x${thumb.height}:${btoa(bin)}`;
263	      },
264	      { png, masks, thumb: THUMB, viewport: VIEWPORT },
265	    );
266	  } finally {
267	    await scratch.close();
268	  }
269	}
270	
271	export async function settle(page: Page): Promise<void> {
272	  // The real portal keeps background connections open, so "network idle" may never come.
273	  await page.waitForLoadState("networkidle", { timeout: 5000 }).catch(() => undefined);
274	}
275	
276	export async function capture(
277	  browser: Browser,
278	  page: Page,
279	  calls: Recorder,
280	  full: boolean,
281	): Promise<Record<string, Json>> {
282	  const screen = normalise(await page.locator("body").ariaSnapshot());
283	  if (!full) return { screen, requests: await calls.take() };
284	  return {
285	    screen,
286	    requests: await calls.take(),
287	    layout: await layout(page),
288	    thumbnail: await thumbnail(browser, page),
289	  };
290	}
291	
292	export async function accountState(stripe: Stripe, subscription: string): Promise<Json> {
293	  const sub = await stripe.subscriptions.retrieve(subscription, { expand: ["items.data.price"] });
294	  const invoices = await stripe.invoices.list({ subscription, limit: 10 });
295	  const customer = typeof sub.customer === "string" ? sub.customer : sub.customer.id;
296	  const pending = await stripe.invoiceItems.list({ customer, pending: true, limit: 20 });
297	  return {
298	    status: sub.status,
299	    cancel_at_period_end: sub.cancel_at_period_end,
300	    cancel_at: sub.cancel_at ?? null,
301	    discounts: sub.discounts.length,
302	    items: sub.items.data.map((i) => ({
303	      amount: i.price.unit_amount,
304	      interval: i.price.recurring?.interval ?? null,
305	      quantity: i.quantity ?? null,
306	      period_end: i.current_period_end,
307	    })),
308	    // Oldest first, so that a new invoice appends instead of shifting every index.
309	    invoices: invoices.data.toReversed().map((inv) => invoiceView(inv)),
310	    // Prorations wait here until the next invoice; amounts sorted, since list order is by time.
311	    pending_items: pending.data
312	      .map((i) => ({ amount: i.amount, description: i.description ?? null }))
313	      .sort(
314	        (a, b) => a.amount - b.amount || (a.description ?? "").localeCompare(b.description ?? ""),
315	      ),
316	  };
317	}
318	
319	export async function launch(): Promise<Browser> {
320	  return chromium.launch();
321	}
322	
323	export async function openPage(browser: Browser): Promise<Page> {
324	  const context = await browser.newContext({
325	    locale: "en-US",
326	    timezoneId: "UTC",
327	    viewport: VIEWPORT,
328	    deviceScaleFactor: 1,
329	  });
330	  return context.newPage();
331	}
332	
333	export async function runWalkthrough(
334	  stripe: Stripe,
335	  input: UiInput,
336	): Promise<Record<string, Json>> {
337	  const portal = await setupWorld(stripe, input);
338	  const full = input.capture === "full";
339	  const browser = await launch();
340	  const out: Record<string, Json> = {};
341	  try {
342	    const page = await openPage(browser);
343	    const calls = watchPortalCalls(page, full);
344	    await page.goto(portal.url);
345	    for (const step of input.steps) {
346	      if (step.do === "capture") {
347	        await page.getByText(step.until, { exact: false }).first().waitFor({ timeout: 20000 });
348	        await settle(page);
349	        out[step.as] = await capture(browser, page, calls, full);
350	      } else {
351	        await act(page, step);
352	      }
353	    }
354	  } finally {
355	    await browser.close();
356	  }
357	  if (full) out.account = await accountState(stripe, portal.subscription);
358	  return out;
359	}
