import fs from 'fs';
const dir='/work/targets/stripe-billing/fixtures/dev/';
const only = process.argv[2] ? new RegExp(process.argv[2]) : null;
const files=fs.readdirSync(dir).filter(f=>!/^(ui|uf|x|l)-/.test(f)).filter(f=>!only||only.test(f));
for(const f of files){
  const fx=JSON.parse(fs.readFileSync(dir+f));
  const p=fx.observed.preview; const i=fx.input;
  let s;
  if(p.error) s='ERR '+JSON.stringify(p.error);
  else s=`sub=${p.subtotal} tot=${p.total} due=${p.amount_due} disc=${JSON.stringify(p.total_discount_amounts.map(d=>d.amount))} reason=${p.billing_reason} created=${p.created} ps=${p.period_start} pe=${p.period_end} | `+p.lines.data.map(l=>`${l.amount}[${l.discount_amounts.map(d=>d.amount)}]{${l.description}} ${l.period.start}-${l.period.end}`).join(' ; ');
  console.log(f, JSON.stringify(i), '\n   ', s, '\n    first', JSON.stringify(fx.observed.first_invoice));
}

