import fs from 'fs';
const dir='/work/targets/stripe-billing/fixtures/dev/';
const files=fs.readdirSync(dir).filter(f=>!/^(ui|uf|x|l)-/.test(f));
const vals=new Map();
function flat(v,p,out){
  if(Array.isArray(v)){ if(!v.length) out.push([p,'[]']); v.forEach((x,i)=>flat(x,p+'[*]',out)); }
  else if(v&&typeof v==='object'){ const k=Object.keys(v); if(!k.length) out.push([p,'{}']); for(const kk of k) flat(v[kk],p?p+'.'+kk:kk,out);}
  else out.push([p,v]);
}
for(const f of files){
  const fx=JSON.parse(fs.readFileSync(dir+f));
  const out=[]; flat(fx.observed.preview,'',out);
  for(const [p,v] of out){ if(!vals.has(p)) vals.set(p,new Map()); const m=vals.get(p); const key=typeof v==='string'?v.replace(/_[A-Za-z0-9]{8,}/g,'_ID'):JSON.stringify(v); m.set(key,(m.get(key)||0)+1);}
}
for(const [p,m] of vals){ const e=[...m.entries()]; console.log(p, e.length>6? `${e.length} distinct e.g. ${e.slice(0,4).map(x=>x[0]).join(' | ')}` : e.map(([k,c])=>`${k}(${c})`).join(' | ')); }

import fs from 'fs';
const dir='/work/targets/stripe-billing/fixtures/dev/';
const files=fs.readdirSync(dir).filter(f=>!/^(ui|uf|x|l)-/.test(f));
const agg=new Map();
for(const f of files){
  const fx=JSON.parse(fs.readFileSync(dir+f));
  const p=fx.observed.preview; if(p.error) continue;
  const i=fx.input;
  const beh=i.change.proration_behavior;
  const key=`beh=${beh} aa=${p.auto_advance} npa=${p.next_payment_attempt===null?'null':p.next_payment_attempt-p.created} created-ps=${p.created-p.period_start} pe-ps=${p.period_end-p.period_start} endbal=${p.ending_balance===0?'0':(p.ending_balance===p.total?'total':'other')} due=${p.amount_due===Math.max(0,p.total)?'max0':'other'}`;
  agg.set(key,(agg.get(key)||[]).concat(f));
}
for(const [k,v] of agg) console.log(v.length,k,v.slice(0,4).join(' '));

