input.content:
import fs from 'fs';
const dir='/work/targets/stripe-billing/fixtures/dev/';
const re=new RegExp(process.argv[2]);
const files=fs.readdirSync(dir).filter(f=>re.test(f));
for(const f of files){
  const fx=JSON.parse(fs.readFileSync(dir+f));
  const p=fx.observed.preview; const i=fx.input;
  console.log('=== '+f, JSON.stringify(i));
  if(p.error){ console.log('  ERR', JSON.stringify(p.error)); continue; }
  const ids=new Map(); const c=(s)=>{ if(s==null) return s; if(!ids.has(s)) ids.set(s, s.split('_').slice(0,-1).join('_')+'#'+(ids.size+1)); return ids.get(s); };
  console.log(`  sub=${p.subtotal} tot=${p.total} due=${p.amount_due} endbal=${p.ending_balance} created=${p.created} ps=${p.period_start} pe=${p.period_end} aa=${p.auto_advance} npa=${p.next_payment_attempt} prd=${p.parent.subscription_details.subscription_proration_date}`);
  console.log(`  discounts=${JSON.stringify(p.discounts.map(c))} tda=${JSON.stringify(p.total_discount_amounts.map(d=>[d.amount,c(d.discount)]))} tpca=${JSON.stringify(p.total_pretax_credit_amounts.map(d=>[d.amount,c(d.discount),d.type]))}`);
  for(const l of p.lines.data){
    const s=l.parent.subscription_item_details;
    console.log(`  ${l.amount} q=${l.quantity} disc=${l.discountable} da=${JSON.stringify(l.discount_amounts.map(d=>[d.amount,c(d.discount)]))} pca=${JSON.stringify(l.pretax_credit_amounts.map(d=>[d.amount,c(d.discount)]))} ld=${JSON.stringify(l.discounts.map(c))} uad=${l.pricing.unit_amount_decimal} price=${c(l.pricing.price_details.price)} si=${c(s.subscription_item)} ii=${s.invoice_item?'ii':null} pr=${s.proration} cred=${s.proration_details.credited_items?'yes':null} ${l.period.start}-${l.period.end} {${l.description}}`);
  }
  console.log('  first', JSON.stringify(fx.observed.first_invoice));
}

