import fs from 'fs';
const dir='/work/targets/stripe-billing/fixtures/dev/';
const files=fs.readdirSync(dir).filter(f=>!/^(ui|uf|x|l)-/.test(f));
const agg=new Map();
for(const f of files){
  const fx=JSON.parse(fs.readFileSync(dir+f));
  const i=fx.input;
  const coupons = i.kind==='wide'? i.coupons : (i.coupon?[i.coupon]:[]);
  const d=i.change.discount;
  const desc = (c)=> (c.percent_off!==undefined?'pct':'off')+(c.duration==='once'?'1':'');
  const key=`${i.billing_mode} items=${i.kind==='wide'?i.items.length:1} coupons=[${coupons.map(desc)}] prev=${d?desc(d):'-'} err=${!!fx.observed.preview.error}`;
  agg.set(key,(agg.get(key)||0)+1);
}
const e=[...agg.entries()].sort((a,b)=>b[1]-a[1]); for(const [k,v] of e) console.log(v,k);

