import fs from 'fs';
const dir='/work/targets/stripe-billing/fixtures/dev/';
export function load(filter){
  return fs.readdirSync(dir).filter(f=>!/^(ui|uf|x|l)-/.test(f)).filter(f=>!filter||filter.test(f)).map(f=>({f,...JSON.parse(fs.readFileSync(dir+f))}));
}
// normalise both shapes
export function norm(fx){
  const i=fx.input;
  if(i.kind==='wide'){
    return {mode:i.billing_mode,start:i.start,interval:i.interval,items:i.items,coupons:i.coupons,change:i.change};
  }
  return {mode:i.billing_mode,start:i.start,interval:i.plan.interval,items:[{amount:i.plan.amount,quantity:i.quantity}],coupons:i.coupon?[i.coupon]:[],
    change:{item:0,amount:i.change.plan?i.change.plan.amount:null,interval:i.change.plan&&i.change.plan.interval!==i.plan.interval?i.change.plan.interval:null,quantity:i.change.quantity,offset:i.change.offset,proration_behavior:i.change.proration_behavior,discount:i.change.discount, planChanged: !!i.change.plan}};
}
export function addMonths(t, months, anchorDay){
  const d=new Date(t*1000);
  const y=d.getUTCFullYear(), m=d.getUTCMonth()+months;
  const last=new Date(Date.UTC(y,m+1,0)).getUTCDate();
  const day=Math.min(anchorDay??d.getUTCDate(),last);
  return Date.UTC(y,m,day,d.getUTCHours(),d.getUTCMinutes(),d.getUTCSeconds())/1000;
}

import {load,norm,addMonths} from './lib.mjs';
const rha=(x)=>Math.sign(x)*Math.round(Math.abs(x)); // half away (float)
const fx=load();
const rows=[];
for(const x of fx){
  const p=x.observed.preview; if(p.error) continue;
  const n=norm(x);
  if(n.items.length!==1) continue;
  if(n.change.interval) continue;
  const lines=p.lines.data.filter(l=>l.parent.subscription_item_details.proration);
  if(lines.length!==2) continue;
  const ps=p.period_start; const P= (n.interval==='month'?addMonths(ps,1):addMonths(ps,12))-ps;
  const prd=p.parent.subscription_details.subscription_proration_date;
  const pe=ps+P; const r=pe-prd, e=prd-ps;
  const it=n.items[0];
  const b=it.amount*it.quantity;
  const na=(n.change.amount??it.amount)*(n.change.quantity ?? (n.change.planChanged||n.change.amount!==null?1:it.quantity));
  rows.push({f:x.f,mode:n.mode,coupons:n.coupons,disc:n.change.discount,b,na,e,r,P,credit:lines[0].amount,charge:lines[1].amount, renew:p.lines.data.filter(l=>!l.parent.subscription_item_details.proration).map(l=>[l.amount,l.discount_amounts.map(d=>d.amount)]), first:x.observed.first_invoice});
}
export {rows};
const mode=process.argv[2];
if(mode==='nocoupon'){
  let ok=0,bad=0;
  for(const r of rows.filter(r=>!r.coupons.length&&!r.disc)){
    const f=r.r/r.P;
    const cr=-Math.floor((2*r.b*r.r+r.P)/(2*r.P));
    const ch= r.mode==='flexible'? Math.round(r.na*(1-r.e/r.P)) : Math.floor((2*r.na*r.r+r.P)/(2*r.P));
    if(cr===r.credit&&ch===r.charge) ok++; else {bad++; console.log(r.f,r.mode,r.b,r.na,r.e,r.r,r.P,'exp',r.credit,r.charge,'got',cr,ch, r.na*r.r/r.P);}
  }
  console.log('ok',ok,'bad',bad);
}
if(mode==='dump'){
  for(const r of rows.filter(r=>r.coupons.length||r.disc)) console.log(JSON.stringify(r));
}

