import {rows} from './hyp.mjs';
const rh=(x)=>Math.sign(x)*Math.round(Math.abs(x));
const ratRound=(num,den)=>Math.floor((2*num+den)/(2*den)); // half up positive
const single=rows.filter(r=>r.coupons.length===1&&!r.disc);
const res={};
function tally(name, ok){ res[name]=res[name]||{ok:0,bad:0,badf:[]}; if(ok) res[name].ok++; else {res[name].bad++; res[name].badf.push(ok===false?'':ok);} }
for(const r of single){
  const c=r.coupons[0]; const f=r.r/r.P; const ff=1-r.e/r.P;
  const p=c.percent_off!==undefined? c.percent_off/100 : null;
  const D1 = p!==null? Math.round(r.b*p) : Math.min(c.amount_off, r.b);   // discount on first invoice
  const credits={
    A_round_bD_f: -rh((r.b-D1)*f),
    B_rbf_minus_rDf: -(rh(r.b*f)-rh(D1*f)),
    C_pct_direct: p!==null? -rh(r.b*(1-p)*f) : null,
    D_rat: -ratRound((r.b-D1)*r.r, r.P),
    E_rbf_minus_rbfp: p!==null? -(rh(r.b*f)-rh(rh(r.b*f)*p)) : null,
  };
  for(const [k,v] of Object.entries(credits)) if(v!==null) tally(`${r.mode} ${p!==null?'pct':'off'+(c.duration==='once'?'1':'')} credit ${k}`, v===r.credit || r.f+` exp ${r.credit} got ${v}`);
  // charge
  const once=c.duration==='once';
  const nf_flex=Math.round(r.na*ff), nf_cl=ratRound(r.na*r.r,r.P);
  const D2 = once?0: (p!==null? Math.round(r.na*p): Math.min(c.amount_off, r.na));
  const charges={
    A_nf_minus_D2f_flex: nf_flex - rh(D2*f),
    A2_nf_minus_D2ff_flex: nf_flex - Math.round(D2*ff),
    B_nf_minus_D2f_cl: nf_cl - rh(D2*f),
    C_round_nD2_f: rh((r.na-D2)*f),
    C2_round_nD2_ff: Math.round((r.na-D2)*ff),
    E_pct_direct_ff: p!==null&&!once? Math.round(r.na*ff*(1-p)) : null,
    F_nf_minus_rnfp: p!==null&&!once? nf_flex-Math.round(nf_flex*p) : null,
    G_cl_nf_minus_rnfp: p!==null&&!once? nf_cl-Math.round(nf_cl*p) : null,
  };
  for(const [k,v] of Object.entries(charges)) if(v!==null) tally(`${r.mode} ${p!==null?'pct':'off'+(once?'1':'')} charge ${k}`, v===r.charge || r.f+` exp ${r.charge} got ${v}`);
}
for(const [k,v] of Object.entries(res).sort()) console.log(k, v.ok, v.bad, v.badf.slice(0,3).join(' | '));

