input.content:
import {load,norm} from './lib.mjs';
// For each fixture with discounts, label the di ids by coupon spec using tda / first-invoice is not available, so label by order.
for(const x of load()){
  const p=x.observed.preview; const n=norm(x);
  const cs=n.coupons.length+(n.change.discount?1:0);
  if(cs<2 && !(process.argv[2]==='all' && cs>=1)) continue;
  if(p.error){ console.log(x.f,'ERR',p.error.message.slice(0,60)); continue;}
  const ids=new Map(); const c=(s)=>{ if(!ids.has(s)) ids.set(s,'D'+(ids.size+1)); return ids.get(s); };
  const desc=(c)=>(c.percent_off!==undefined?c.percent_off+'%':'$'+c.amount_off)+(c.duration==='once'?'/1':'');
  console.log(`${x.f} ${n.mode} items=${n.items.length} chg=${n.change.item} coupons=[${n.coupons.map(desc)}] prev=${n.change.discount?desc(n.change.discount):'-'}`);
  console.log(`   top=${p.discounts.map(c)} tda=${JSON.stringify(p.total_discount_amounts.map(d=>[d.amount,c(d.discount)]))}`);
  for(const l of p.lines.data) console.log(`   ${l.amount} da=${JSON.stringify(l.discount_amounts.map(d=>[d.amount,c(d.discount)]))} ${l.description.replace(/ after.*/,'')}`);
}

