1	/**
2	 * Removes secrets and personal data from recorded observations before they reach the repo.
3	 * Literal replacements (account names and the like) come from a file outside the repository, so
4	 * the mapping itself is never committed.
5	 */
6	import { existsSync, readFileSync } from "node:fs";
7	import { z } from "zod";
8	import type { Json } from "./json.ts";
9	
10	const SECRET_PATTERNS: [RegExp, string][] = [
11	  [/\b[sprk]k_(test|live)_[A-Za-z0-9]+/g, "key_REDACTED"],
12	  [/secret=[^&"\s]+/g, "secret=REDACTED"],
13	  [/[\w.+-]+@[\w-]+\.[a-z.]{2,}/gi, "user@example.com"],
14	];
15	
16	const LiteralMap = z.record(z.string(), z.string());
17	
18	export function loadLiterals(file: string | undefined): Record<string, string> {
19	  if (file === undefined || !existsSync(file)) return {};
20	  return LiteralMap.parse(JSON.parse(readFileSync(file, "utf8")));
21	}
22	
23	function scrubText(text: string, literals: Record<string, string>): string {
24	  let s = text;
25	  for (const [re, rep] of SECRET_PATTERNS) s = s.replace(re, rep);
26	  for (const [from, to] of Object.entries(literals)) s = s.split(from).join(to);
27	  return s;
28	}
29	
30	// Keys are scrubbed too: some observations are keyed by on-screen text.
31	export function scrub(value: Json, literals: Record<string, string>): Json {
32	  if (typeof value === "string") return scrubText(value, literals);
33	  if (Array.isArray(value)) return value.map((v) => scrub(v, literals));
34	  if (value !== null && typeof value === "object") {
35	    const o: Record<string, Json> = {};
36	    for (const [k, v] of Object.entries(value)) o[scrubText(k, literals)] = scrub(v, literals);
37	    return o;
38	  }
39	  return value;
40	}
41	
42	// Used by the pre-commit test on committed fixtures.
43	export function findSecrets(text: string): string[] {
44	  const hits: string[] = [];
45	  for (const [re] of SECRET_PATTERNS) {
46	    for (const m of text.matchAll(new RegExp(re.source, re.flags))) {
47	      if (!["key_REDACTED", "secret=REDACTED", "user@example.com"].includes(m[0])) hits.push(m[0]);
48	    }
49	  }
50	  if (/authorization|set-cookie/i.test(text)) hits.push("auth header");
51	  return hits;
52	}
