150	// Runs every event of the clock's customers up to `to`, in time order.
151	export function advanceClock(state: State, clock: Clock, to: number): void {
152	  const customers = new Set(
153	    Object.values(state.customers)
154	      .filter((c) => c.clock === clock.id)
155	      .map((c) => c.id),
156	  );
157	  for (let guard = 0; guard < 1000; guard += 1) {
158	    let next: { at: number; run: () => void } | null = null;
159	    const consider = (at: number, run: () => void): void => {
160	      if (at <= to && (next === null || at < next.at)) next = { at, run };
161	    };
162	    for (const sub of Object.values(state.subscriptions)) {
163	      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
164	      const cancelAt = sub.cancel_at;
165	      if (cancelAt !== null && cancelAt <= sub.period_end) {
166	        consider(cancelAt, () => {
167	          sub.status = "canceled";
168	          sub.ended_at = cancelAt;
169	        });
170	        continue;
171	      }
172	      consider(sub.period_end, () => {
173	        if (sub.cancel_at_period_end) {
174	          sub.status = "canceled";
175	          sub.ended_at = sub.period_end;
176	        } else {
177	          renew(state, sub);
178	        }
179	      });
180	    }
181	    for (const inv of Object.values(state.invoices)) {
182	      if (!customers.has(inv.customer)) continue;
183	      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
184	        const at = inv.next_payment_attempt;
185	        if (at !== null) {
186	          consider(at, () => {
187	            attempt(state, inv, at);
188	          });
189	        }
190	      }
191	    }
192	    const chosen: { at: number; run: () => void } | null = next;
193	    if (chosen === null) break;
194	    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
195	    chosen.run();
196	  }
197	  clock.frozen_time = to;
198	}
